INSERT INTO `b_job` (`id`, `user_id`, `employer_id`, `title`, `description`, `state`, `status`, `created_at`, `updated_at`, `country`, `city`, `street_address`, `expiration_date`, `highlight`, `schedule`, `start_date`, `year_of_experience`, `pay_rate`, `pay_rate_hourly`, `pay_rate_daily`, `profession_id`, `speciality_id`, `work_type`, `need`, `blocked`, `job_id`, `verified`, `archived`, `annual_salary`, `monthly_salary`, `salary_type`, `rank`) VALUES
(0x0194d44d57847aa385199480cbb498d3, 0x0194d44cfc837db2b43674d7e2a4b80a, NULL, 'dffsdf', '<p>wewewe</p>', 'wewe', 'draft', '2025-02-05 04:10:26', '2025-02-05 04:10:26', '', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL),
(0x019537fffe7375dc97e4199be1d9529d, 0x0195000f5fb4792d928e7c5c0001ebb0, 0x0195000f6d21710d9a5e92a452b8f45c, 'ABCD Wound Care Need', '<p>Hours are 7a-4p<br />\r\nApprox. 2 shifts per week<br />\r\nProvider picks their own schedule<br />\r\nCredentialing timeframe 30-45 days<br />\r\nMust be comfortable commuting up to 65 miles per day<br />\r\nMileage will be reimbursed<br />\r\nNo call/weekends<br />\r\nMajority of patients seen will be geriatric, nursing home travel<br />\r\nAverage patients per day 20-25<br />\r\nMust be comfortable with debridement&#39;s and cauterization<br />\r\nEMR - In-House system that is easy to learn<br />\r\nLocal candidates only<br />\r\nSupplies and Tablet Provided</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Title:&nbsp;DNP, NP</p>\r\n\r\n<p>Specialty:&nbsp;Wound Care</p>\r\n\r\n<p>Location:&nbsp;MO</p>\r\n\r\n<p>Job Type:&nbsp;Locum Tenens</p>\r\n\r\n<p>Board Certification:&nbsp;Yes</p>\r\n\r\n<p>On Call:&nbsp;No</p>\r\n\r\n<p>Compensation:</p>\r\n\r\n<p>Telemedicine:&nbsp;No</p>\r\n\r\n<p>Government:&nbsp;No</p>\r\n\r\n<p>Reference ID:&nbsp;JN -062024-17356</p>\r\n\r\n<ul>\r\n	<li>ASAP</li>\r\n	<li>Ongoing</li>\r\n</ul>', 'MD', 'published', '2025-02-24 12:47:58', '2025-03-15 09:44:48', 'US', 'Necessitatibus', 'Tempor ipsum', '2025-03-18', '<ul>\r\n	<li>Must be comfortable commuting up to 65 miles per day</li>\r\n	<li>Credentialing timeframe 30-45 days</li>\r\n	<li>Provider picks their own schedule</li>\r\n</ul>', '7a-4p 2 shifts per week', '2025-01-30', 2, 'Daily', NULL, 90, 0x01953387523a7fcca8525bc9d40a9f2e, 0x0195339527fd72ee85d40d6f91bce7a6, 'Full time', 'Long term', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL),
(0x01953805adc2724eb9c7cfc293351b7b, 0x0195000f5fb4792d928e7c5c0001ebb0, 0x0195000f6d21710d9a5e92a452b8f45c, 'Wound Care Physician Needed in XYZ, NY', '<p>Support Staff: PAs, RNs, LPNs, CHTs, and PSCs<br />\r\nSchedule Details: Monday Friday 8a-5pm<br />\r\n<br />\r\nWork Details:<br />\r\nPractice Setting: Clinic&mdash;Floating between 3 that are 30 min apart. The will not travel to all 3 in the same day. It will be one location each day<br />\r\nEMR/Charting Software: epic<br />\r\nAvg. Daily Census: 18-22 (including HBO patients)<br />\r\nPatient Age Group: 13 years and older<br />\r\nProcedures: Seeing patients with leg ulcers, non healing surgical wounds, limb preservations, 1st and 2nd degree burns, VAC, Compression therapy, skin grafts and flaps.<br />\r\n<br />\r\nRequirements:<br />\r\nBoard Certifications required (Wound Care and Hyperbaric Medicine)<br />\r\nState License(s): NC<br />\r\nDEA Req&rsquo;d?: yes<br />\r\nYears of Experience Req&rsquo;d: 1 year experience<br />\r\nCredentialing Timeframe: 60-90 days<br />\r\n<br />\r\nWilling To License?: No<br />\r\n<br />\r\nName Clear: Required with NPI<br />\r\n<br />\r\nTravel: flight, hotel, rental car or lodging</p>', 'HI', 'closed', '2025-02-24 12:54:11', '2025-02-28 13:19:07', 'US', 'Downtown', 'Ulkavo', '2025-03-29', '<ul>\r\n	<li>Practice Setting: Clinic&mdash;Floating between 3 that are 30 min apart.</li>\r\n	<li>EMR/Charting Software: epic</li>\r\n	<li>Avg. Daily Census: 18-22 (including HBO patients)</li>\r\n</ul>', 'Monday Friday 8a-5pm', '2025-02-23', 5, 'Daily', NULL, 200, 0x01953387523a7fcca8525bc9d40a9f2e, 0x0195339527fd72ee85d40d6f91bce7a6, 'Part time', 'Routine', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL),
